#include <stdio.h>

int main() {
    int n;
    printf("Enter a number: ");
    scanf("%d", &n);

    if (n % 2 == 0) {
        printf("%d is even.\n", n);
    } else {
        printf("%d is odd.\n", n);
    }

    return 0;
}

#include <stdio.h>

int main() {
    int i;
    printf("Series: ");
    for (i = 2; i <= 100; i = i + 2) {
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}
